def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colorings of the grid extending its fixed digits.

    Replace each '?' by '1', '2', or '3' so every pair of edge-sharing
    cells has different digits. Return the count modulo 998244353.
    H and W are positive and H * W <= 200.
    """
    mod = 998244353

    # Keep the frontier on the shorter dimension (at most 14 cells).
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Two bits per frontier cell; zero means it has not been visited.
    # Immediately before visiting (r, c), slot c contains its upper
    # neighbor, while slot c-1 contains its left neighbor.
    dp = {0: 1}
    for r in range(H):
        for c in range(W):
            shift = 2 * c
            slot_mask = 3 << shift
            fixed = grid[r][c]
            choices = (1, 2, 3) if fixed == "?" else (int(fixed),)
            next_dp = {}
            for state, count in dp.items():
                above = (state >> shift) & 3
                left = (state >> (shift - 2)) & 3 if c else 0
                cleared = state & ~slot_mask
                for color in choices:
                    if color != above and color != left:
                        new_state = cleared | (color << shift)
                        next_dp[new_state] = (
                            next_dp.get(new_state, 0) + count
                        ) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

