from functools import lru_cache
from math import gcd


# Every possible digit sum is at most 81. These are the largest
# powers of the digit-product primes that can divide such a sum.
_PRODUCT_CAP = 2**6 * 3**4 * 5**2 * 7**2


@lru_cache(maxsize=None)
def _products_after_digit(product):
    return tuple(gcd(product * digit, _PRODUCT_CAP) for digit in range(1, 10))


@lru_cache(maxsize=None)
def _count_suffix(remaining, digit_sum, product):
    if remaining == 0:
        return int(digit_sum > 0 and product % digit_sum == 0)
    if product == 0:
        # A non-leading zero makes every completion beautiful.
        return 10**remaining

    result = _count_suffix(
        remaining - 1, digit_sum, 1 if digit_sum == 0 else 0
    )
    for digit, next_product in enumerate(_products_after_digit(product), 1):
        result += _count_suffix(remaining - 1, digit_sum + digit, next_product)
    return result


def _count_up_to(bound):
    if bound <= 0:
        return 0
    digits = [int(digit) for digit in str(bound)]
    result = 0
    digit_sum = 0
    product = 1
    for index, limit in enumerate(digits):
        remaining = len(digits) - index - 1
        for digit in range(limit):
            next_product = (
                (1 if digit_sum == 0 else 0)
                if digit == 0
                else (gcd(product * digit, _PRODUCT_CAP) if product else 0)
            )
            result += _count_suffix(remaining, digit_sum + digit, next_product)
        product = (
            (1 if digit_sum == 0 else 0)
            if limit == 0
            else (gcd(product * limit, _PRODUCT_CAP) if product else 0)
        )
        digit_sum += limit
    return result + int(digit_sum > 0 and product % digit_sum == 0)


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is
    divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive).
        r: The upper bound of the range (inclusive).

    Returns:
        The count of beautiful numbers in the range [l, r].

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

