def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    """Return the minimum moves from s to t, or -1 if unreachable.

    There are n stones ('B' or 'W') in cells 1 through n and two
    adjacent empty cells at n+1 and n+2. A move transfers any adjacent
    pair of stones to the empty cells, preserving the pair's order.
    The target has t in cells 1 through n and the last two cells empty.
    The supported range is 2 <= n <= 14.
    """
    if s == t:
        return 0
    if s.count("W") != t.count("W"):
        return -1

    # White stones use one bit each; black stones and holes use zero.
    # Store the first hole's index above the n+2 cell bits.
    shift = n + 2
    cell_mask = (1 << shift) - 1

    def encode(stones: str) -> int:
        whites = sum(1 << i for i, stone in enumerate(stones) if stone == "W")
        return whites | (n << shift)

    start, goal = encode(s), encode(t)
    front, back = {start}, {goal}
    distance_front, distance_back = {start: 0}, {goal: 0}
    sources = [
        [i for i in range(n + 1) if abs(i - hole) > 1]
        for hole in range(n + 1)
    ]

    # Every move is reversible, so search from both endpoints.
    while front and back:
        if len(front) > len(back):
            front, back = back, front
            distance_front, distance_back = distance_back, distance_front

        next_front = set()
        for state in front:
            hole = state >> shift
            whites = state & cell_mask
            next_distance = distance_front[state] + 1
            for source in sources[hole]:
                pair = (whites >> source) & 3
                moved = whites ^ (pair << source) ^ (pair << hole)
                neighbor = moved | (source << shift)
                if neighbor in distance_front:
                    continue
                if neighbor in distance_back:
                    return next_distance + distance_back[neighbor]
                distance_front[neighbor] = next_distance
                next_front.add(neighbor)
        front = next_front

    return -1

