from functools import lru_cache


def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    """Count integers x in [num1, num2] with digit sum in [min_sum, max_sum].

    Return the count modulo 10^9 + 7. Bounds are numeric strings with
    1 <= num1 <= num2 <= 10^22, and 1 <= min_sum <= max_sum <= 400.

    >>> count_good_integers("1", "12", 1, 8)
    11
    >>> count_good_integers("1", "5", 1, 5)
    5
    """
    modulus = 10**9 + 7

    def count_upto(bound: str) -> int:
        digits = tuple(map(int, bound))
        length = len(digits)

        @lru_cache(None)
        def dp(position: int, digit_sum: int, tight: bool) -> int:
            if digit_sum > max_sum:
                return 0
            if digit_sum + 9 * (length - position) < min_sum:
                return 0
            if position == length:
                return int(min_sum <= digit_sum <= max_sum)
            limit = digits[position] if tight else 9
            total = 0
            for digit in range(limit + 1):
                total += dp(position + 1, digit_sum + digit,
                            tight and digit == limit)
            return total % modulus

        # Leading zeros give every integer in [0, bound] one representation.
        return dp(0, 0, True)

    lower_is_good = min_sum <= sum(map(int, num1)) <= max_sum
    return (count_upto(num2) - count_upto(num1) + lower_is_good) % modulus

