def max_partitions_with_one_change(s: str, k: int) -> int:
    """Return the maximum greedy partition count after at most one letter change.

    Each partition is the longest remaining prefix with at most k distinct
    lowercase letters. The input has length 1..10000 and 1 <= k <= 26.
    """
    if k == 26:
        return 1

    # A state records the current partition's letters and the number of
    # completed partitions. For equal masks, the higher count dominates.
    changed = {}
    original_mask = 0
    original_count = 0
    for char in s:
        bit = 1 << (ord(char) - ord('a'))
        following = {}
        for mask, count in changed.items():
            combined = mask | bit
            if combined.bit_count() > k:
                combined = bit
                count += 1
            if count > following.get(combined, -1):
                following[combined] = count

        # Spend the optional change at this position on the unedited path.
        for letter in range(26):
            replacement = 1 << letter
            if replacement == bit:
                continue
            combined = original_mask | replacement
            count = original_count
            if combined.bit_count() > k:
                combined = replacement
                count += 1
            if count > following.get(combined, -1):
                following[combined] = count

        combined = original_mask | bit
        if combined.bit_count() > k:
            original_mask = bit
            original_count += 1
        else:
            original_mask = combined
        changed = following

    return max(original_count, max(changed.values(), default=0)) + 1

